import itertools
import json

historians = ("Farley", "Garcia", "Holden", "Jiang")
topics = ("lithographs", "oil paintings", "sculptures", "watercolors")
counts = dict.fromkeys("ABCDE", 0)
total = 0
counterexamples = {}

for historian_order in itertools.permutations(historians):
    h = {name: i for i, name in enumerate(historian_order)}
    if not (h["Holden"] < h["Garcia"] and h["Holden"] < h["Jiang"]):
        continue

    for topic_order in itertools.permutations(topics):
        t = {topic: i for i, topic in enumerate(topic_order)}
        if not (
            t["oil paintings"] < t["lithographs"]
            and t["watercolors"] < t["lithographs"]
            and h["Farley"] < t["oil paintings"]
        ):
            continue

        total += 1
        truths = {
            "A": h["Farley"] < t["sculptures"],
            "B": h["Holden"] < t["lithographs"],
            "C": t["sculptures"] < h["Garcia"],
            "D": t["sculptures"] < h["Jiang"],
            "E": t["watercolors"] < h["Garcia"],
        }
        for option, truth in truths.items():
            counts[option] += int(truth)
            if not truth and option not in counterexamples:
                counterexamples[option] = list(zip(historian_order, topic_order))

must_be_true = [option for option, count in counts.items() if total and count == total]
answer = must_be_true[0] if len(must_be_true) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "valid_schedules": total,
        "true_counts": counts,
        "counterexamples": counterexamples
    }
}, separators=(",", ":")))
